-- The audit trigger 0002 attached to every table that existed then, on the
-- five tables 0027 creates (issue #287): a table created later gets none
-- unless its migration adds it, and who edited, published, reordered or
-- removed a post, changed the summit or added a tag must be logged.
DROP TRIGGER IF EXISTS audit_row_changes ON public.outreach_tags;
--> statement-breakpoint
CREATE TRIGGER audit_row_changes AFTER INSERT OR UPDATE OR DELETE ON public.outreach_tags FOR EACH ROW EXECUTE FUNCTION public.log_db_changes();
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_row_changes ON public.outreach_posts;
--> statement-breakpoint
CREATE TRIGGER audit_row_changes AFTER INSERT OR UPDATE OR DELETE ON public.outreach_posts FOR EACH ROW EXECUTE FUNCTION public.log_db_changes();
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_row_changes ON public.outreach_post_versions;
--> statement-breakpoint
CREATE TRIGGER audit_row_changes AFTER INSERT OR UPDATE OR DELETE ON public.outreach_post_versions FOR EACH ROW EXECUTE FUNCTION public.log_db_changes();
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_row_changes ON public.outreach_post_tags;
--> statement-breakpoint
CREATE TRIGGER audit_row_changes AFTER INSERT OR UPDATE OR DELETE ON public.outreach_post_tags FOR EACH ROW EXECUTE FUNCTION public.log_db_changes();
