SELECT "id", 'published', 'Wings for Life, Aosta', '2025-05-04', 'Aosta, Italy', 'About thirty of us ran the first Aosta edition of the Wings for Life World Run, invited by Red Bull, and raised about €800 for spinal cord research.', 'About thirty of us ran the first Aosta edition of the Wings for Life World Run and raised about €800 for spinal cord research.', 'About thirty of us ran the first Aosta edition of the Wings for Life World Run, invited by Red Bull, for spinal cord research.', '[{"kind":"paragraph","text":"On May 4th 2025, the team had the pleasure to join the first-ever Aosta edition of the Wings for Life World Run, invited by Red Bull. Around thirty of us ran ‘for those who can’t’, supporting research into spinal cord injuries through this global solidarity run. Our participation fees helped raise around €800 for the cause."}]'::jsonb, '[{"src":"/outreach/wings-for-life-aosta.webp","alt":"About thirty team members in running gear at the Wings for Life World Run in Aosta."}]'::jsonb, '{"linkedin":{"url":"https://www.linkedin.com/posts/politorocketteam_aosta-supportingresearch-invitation-activity-7328733962451816450-CyiE","caption":"On May 4th 2025, the team had the pleasure to join the first-ever Aosta edition of the Wings for Life World Run…"}}'::jsonb FROM "post" RETURNING "post_id")
