SELECT "id", 'published', 'IRESS, 3rd edition', '2025-04-28', 'Rome, Italy', 'In Rome, hosted by SASA. Sophia High Tech joined our talk with a lecture on additive manufacturing.', NULL, 'The summit we started went to Rome for its third edition, hosted by SASA, and our talk brought in Sophia High Tech.', '[{"kind":"paragraph","text":"This year again, a delegation from the PoliTo Rocket Team took part in the annual IRESS conference, now in its third edition, this time hosted in Rome by SASA (Sapienza Aerospace Student Association). Rocketry teams from different Italian universities participated, each presented a short presentation on SRAD innovations. During the Polito Rocket team’s talk, Sophia High Tech also took part with a lecture on the use of additive manufacturing. It was an exceptional opportunity to catch up with all the teams, socialize and keep the rocketry community together, which is getting bigger year after year. A special thanks to SASA for organizing this amazing event."}]'::jsonb, '[{"src":"/outreach/iress-2025-rome.webp","alt":"Students from Italy''s rocket teams on stage under a fresco at IRESS 2025 in Rome."}]'::jsonb, '{"linkedin":{"url":"https://www.linkedin.com/feed/update/urn:li:activity:7327728741634203648/","caption":"This year again, a delegation from the PoliTo Rocket Team took part in the annual IRESS conference, now in its third edition…"}}'::jsonb FROM "post" RETURNING "post_id")
