SELECT "id", 'published', 'Cassini Hackathon', '2024-11-22', NULL, 'We sponsored the 8th CASSINI Hackathon on defence and security, with Fondazione E. Amaldi and EUSPA.', 'We sponsored the 8th CASSINI Hackathon on defence and security.', 'We sponsored the 8th CASSINI Hackathon, “Defence and Security”, with Fondazione E. Amaldi and EUSPA.', '[{"kind":"paragraph","text":"The team proudly participated in the 8th CASSINI Hackathon ‘Defence and Security’, sponsored in collaboration with Fondazione E. Amaldi and EUSPA. This event fostered innovation in space technologies, challenging participants to tackle geospatial intelligence, drone security operations, and space maneuver simulations. Acting as a sponsor, the team was able to connect with students and graduates, mentors and experts, creating a dynamic ecosystem for groundbreaking ideas. The hackathon highlighted the power of collaboration to drive innovation in Europe’s defence and security sectors."}]'::jsonb, '[{"src":"/outreach/cassini-hackathon.webp","alt":"Five team members at a panel table with microphones during the CASSINI Hackathon."}]'::jsonb, '{"linkedin":{"url":"https://www.linkedin.com/posts/fondazione-e-amaldi_defis-euspace-europeanleagueofeconomycooperation-activity-7269678120851382273-jt43","caption":"The team proudly participated in the 8th CASSINI Hackathon ‘Defence and Security’, sponsored in collaboration with Fondazione E. Amaldi…","account":"Fondazione E. Amaldi"}}'::jsonb FROM "post" RETURNING "post_id")
