SELECT "id", 'published', 'IAC 2024, Milan', '2024-10-14', 'Milan, Italy', 'At the largest IAC ever we showed Cavour and presented two papers, winning the Geography, Generation, Gender award.', 'At the largest IAC ever we showed Cavour, presented two papers and won an award.', 'We showed Cavour and our rocket parts at the 75th International Astronautical Congress, the largest IAC in history, and came home with an award.', '[{"kind":"paragraph","text":"The team attended the 75th International Aeronautical Congress in Milan, showcasing our rocket components and the Cavour rocket at the largest IAC in history. During the event, we participated in the Student Team Challenge, presenting a paper on the sustainable design of our liquid rocket engine Efesto, earning the Geography, Generation, Gender award for our commitment to inclusivity. Additionally, we presented a paper on the innovative structure of Cavour’s fins, highlighting our dedication to engineering excellence and innovation."},{"kind":"highlight","label":"AWARD","text":"Geography, Generation, Gender award · Student Team Challenge"}]'::jsonb, '[{"src":"/outreach/iac-2024-milan.webp","alt":"Team members on stage at IAC 2024 under a screen reading Geography, Generation, Gender award."}]'::jsonb, '{"instagram":{"url":"https://www.instagram.com/p/DCJ3SWOCRaU/","caption":"The team attended the 75th International Aeronautical Congress in Milan, showcasing our rocket components and the Cavour rocket…"}}'::jsonb FROM "post" RETURNING "post_id")
