SELECT "id", 'published', 'PLD Space award', '2024-07-11', 'Padova, Italy', 'We won the PLD Space Program Management Challenge at IRESS 2024.', NULL, 'We won the PLD Space Program Management Challenge at IRESS 2024, against Italy''s best university rocketry teams.', '[{"kind":"paragraph","text":"Competing among Italy’s finest university rocketry teams, we proudly demonstrated exceptional dedication, skills, and teamwork to win the PLD Space Program Management Challenge at IRESS 2024. This prestigious competition tested the management and leadership capabilities through the evaluation of innovative rocket launcher projects. A heartfelt thank you to PLD Space and all collaborators for this incredible opportunity, which marks a significant milestone in our journey toward excellence in space exploration and innovation."},{"kind":"highlight","label":"AWARD","text":"PLD Space Program Management Challenge · IRESS 2024"}]'::jsonb, '[{"src":"/outreach/pld-space-award.webp","alt":"A graphic reading Program Management Challenge Winners 2024 over a photo of the team."}]'::jsonb, '{"linkedin":{"url":"https://www.linkedin.com/posts/pld-space_spacetalent-activity-7216740388290629632-WDmu","caption":"Competing among Italy’s finest university rocketry teams, we proudly demonstrated exceptional dedication, skills, and teamwork…","account":"PLD Space"}}'::jsonb FROM "post" RETURNING "post_id")
