SELECT "id", 'published', 'FormNext, Frankfurt', '2024-05-19', 'Frankfurt, Germany', 'Our design and additive manufacturing division visited the world’s leading 3D-printing expo; Cavour’s fins drew a lot of interest.', NULL, 'Our Design & Additive Manufacturing Division went to FormNext, the world’s leading expo for industrial 3D printing.', '[{"kind":"paragraph","text":"The Design & Additive Manufacturing Division recently attended FormNext Expo in Frankfurt, Germany, the world’s leading event for additive manufacturing and industrial 3D printing. The exhibition showcased cutting-edge advancements and fostered collaboration among industry leaders and innovators. Our team engaged with experts, gaining valuable insights into emerging technologies. Particular attention was drawn to the innovative design of Cavour’s fins assembly, which sparked significant interest and highlighted our commitment to excellence in aerospace engineering."}]'::jsonb, '[{"src":"/outreach/formnext-frankfurt.webp","alt":"An audience in a hall at FormNext watching a talk on topology optimisation."}]'::jsonb, '{"instagram":{"url":"https://www.instagram.com/p/CzgVPXVtBLq/","caption":"The Design & Additive Manufacturing Division recently attended FormNext Expo in Frankfurt, Germany…"}}'::jsonb FROM "post" RETURNING "post_id")
