SELECT "id", 'published', 'Hosting Space Eagle', '2022-11-25', 'Torino, Italy', 'We hosted Space Eagle, a high school rocketry group, with guided tours and hands-on workshops.', NULL, 'We hosted Space Eagle, a high school rocketry group, for guided tours and hands-on workshops.', '[{"kind":"paragraph","text":"STEM Outreach goes beyond inspiration; it sparks meaningful exchanges. Recently, PoliTo Rocket Team hosted Space Eagle, a talented high school rocketry group. Guided tours, hands-on workshops, and a remarkable collection unfolded, shaping the future of STEM education."}]'::jsonb, '[{"src":"/outreach/hosting-space-eagle.webp","alt":"High school students from Space Eagle with team members in the workshop."}]'::jsonb, '{"instagram":{"url":"https://www.instagram.com/p/CrTSz02N8J-/","caption":"STEM Outreach goes beyond inspiration; it sparks meaningful exchanges. Recently, PoliTo Rocket Team hosted Space Eagle…"}}'::jsonb FROM "post" RETURNING "post_id")
